import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Resources/app_icons.dart';import '../../../../Core/Resources/app_fonts.dart';import '../../../../Core/Resources/app_colors.dart';class BannerCard extends StatelessWidget {  final String imagePath;  final String caption;  final String price;  const BannerCard({    super.key,    required this.imagePath,    required this.caption,    required this.price,  });  @override  Widget build(BuildContext context) {    return SizedBox(      width: 153.w,      height: 222.h,      child: Column(        mainAxisAlignment: MainAxisAlignment.spaceEvenly,        children: [          Stack(            children: [              Container(                  width: 153.w,                  height: 167.h,                  clipBehavior: Clip.antiAliasWithSaveLayer,                  decoration:                      BoxDecoration(borderRadius: BorderRadius.circular(8)),                  child: Image.asset(                    imagePath,                    fit: BoxFit.contain,                  )),              Positioned(                top: 20.h,                left: 5.w,                child: RotationTransition(                  turns: const AlwaysStoppedAnimation(-10 / 360),                  child: Container(                    height: 22.h,                    width: 62.w,                    clipBehavior: Clip.antiAliasWithSaveLayer,                    decoration: BoxDecoration(                      color: AppColors.primaryColor,                      borderRadius: BorderRadiusDirectional.circular(50.r),                    ),                    child: Center(                      child: Text(                        "عرض 34%",                        style: AppTextStyles.bodyXtraSmallMedium,                      ),                    ),                  ),                ),              ),              Positioned(                top: 20.h,                right: 5.w,                child: AppIcons.heartsOutline,              )            ],          ),          Expanded(            child: Column(              mainAxisAlignment: MainAxisAlignment.center,              children: [                Text(                  caption,                  style: AppTextStyles.bodyMediumSemiBold,                  maxLines: 2,                  textAlign: TextAlign.center,                ),                10.verticalSpace,                Row(                  mainAxisAlignment: MainAxisAlignment.center,                  children: [                    Text(                      price,                      style: AppTextStyles.bodySmallSemiBold,                    ),                    6.horizontalSpace,                    Text(                      price,                      style: AppTextStyles.bodyXtraSmallMedium.copyWith(                        color: AppColors.grayscale60,                        decoration: TextDecoration.lineThrough,                        decorationThickness: 3.w,                        decorationColor: AppColors.grayscale60,                        decorationStyle: TextDecorationStyle.solid,                      ),                      // style: context.getTextStyle.headlineMedium,                    ),                  ],                ),              ],            ),          ),        ],      ),    );  }}